VALIDATION=json.loads("[\n  [\n    \"reasoning\",\n    \"holdout-ratio\",\n    \"A pump delivers 18 litres in 3 minutes at a constant rate. How long to deliver 42 litres?\",\n    \"7 minutes.\"\n  ],\n  [\n    \"coding\",\n    \"holdout-null-key\",\n    \"Why should dictionary lookups distinguish a missing key from a key explicitly mapped to None?\",\n    \"A missing key may require a default or indicate absent data, whereas a present key mapped to None can represent an intentional empty value. Use membership testing if the distinction matters.\"\n  ],\n  [\n    \"documents\",\n    \"holdout-translation\",\n    \"Traduis en anglais : Les résultats restent provisoires tant que les données ne sont pas validées.\",\n    \"The results remain provisional until the data are validated.\"\n  ],\n  [\n    \"memory\",\n    \"holdout-conflicting-dates\",\n    \"Two equally authoritative dated records disagree and neither supersedes the other. What should the assistant record?\",\n    \"Record both statements with their dates and provenance, and mark the conflict unresolved rather than selecting one without evidence.\"\n  ]\n]")

def build(root):
    root=Path(root)
    root.mkdir(parents=True,exist_ok=False)
    source_sha=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    def row(domain,family,prompt,target):
        return {"domain":domain,"source":"original_public_applied_curriculum_v2:"+family,
                "source_sha256":source_sha,"workflow_family":family,"rights_verified":True,
                "target_origin":"original_authored_fixture",
                "messages":[{"role":"user","content":prompt},{"role":"assistant","content":target}]}
    train=[row(*item[:4]) for item in CASES]
    validation=[row(*item) for item in VALIDATION]
    preferences=[]
    for item,record in zip(CASES,train):
        if item[4] is not None:
            preferences.append({**{k:record[k] for k in ("source","source_sha256","workflow_family","rights_verified","target_origin")},
                "prompt":record["messages"][:-1],"chosen":item[3],"rejected":item[4]})
    for filename,rows in (("train",train),("holdout",validation),("preferences",preferences)):
        with (root/(filename+".jsonl")).open("x",encoding="utf-8") as output:
            for record in rows:output.write(json.dumps(record,ensure_ascii=False)+"\n")
    from scripts.control_ai_adaptation import validate
    _,_,manifest=validate(root/"train.jsonl",root/"holdout.jsonl")
    (root/"manifest.json").write_text(json.dumps(manifest,indent=2)+"\n",encoding="utf-8")
    print(json.dumps(manifest),flush=True)

if __name__=="__main__":
    p=argparse.ArgumentParser()
    p.add_argument("output",type=Path)
    build(p.parse_args().output)
